"use client";

import { useEffect, useState } from "react";
import { useLang } from "@/lib/lang-context";

/* ─────────────────────────────────────────────────────────
 * LOADING STATE — pixel-grid loader for long-running work
 *
 * Variants:
 *   Drive  — square cells, chevron wavefront driving right;
 *            the 650ms cycle is shorter than the sweep, so
 *            two fronts are always in flight
 *   Dots   — same wavefront, circular cells
 *   Orbit  — a comet lapping the grid perimeter
 *
 * Paired with a shimmering label and a live elapsed timer
 * in mono tabular figures. Reduced motion freezes the grid
 * to its dim state; the timer still ticks.
 * ───────────────────────────────────────────────────────── */

const chevron = Array.from({ length: 9 }, (_, i) => {
  const r = Math.floor(i / 3), c = i % 3;
  return (c + Math.abs(r - 1)) * 90;
});

const ORBIT_ORDER = [0, 1, 2, 5, 8, 7, 6, 3];
const orbit = Array.from({ length: 9 }, (_, i) => {
  const k = ORBIT_ORDER.indexOf(i);
  return k === -1 ? null : k * 110;
});

const PATTERNS: Record<string, { delays: (number | null)[]; dur: number; round: boolean }> = {
  Drive: { delays: chevron, dur: 650, round: false },
  Dots: { delays: chevron, dur: 650, round: true },
  Orbit: { delays: orbit, dur: 950, round: false },
};

function useElapsed() {
  const [ds, setDs] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setDs((d) => d + 1), 100);
    return () => clearInterval(t);
  }, []);
  const total = ds / 10;
  if (total < 60) return `${total.toFixed(1)}s`;
  return `${Math.floor(total / 60)}m ${(total % 60).toFixed(1)}s`;
}

export default function LoadingState({
  label = "Churning",
  variant = "Drive",
  lang: propLang,
}: {
  label?: string;
  variant?: string;
  lang?: "en" | "zh";
}) {
  const lang = useLang("loading-state", propLang);
  const zh = lang === "zh";
  const elapsed = useElapsed();
  const displayLabel = zh && label === "Churning" ? "搅拌中" : label;
  const { delays, dur, round } = PATTERNS[variant] ?? PATTERNS.Drive;

  return (
    <div className="flex w-fit items-center gap-2.5">
      <span aria-hidden className="pixel-grid grid grid-cols-[repeat(3,4px)] gap-[1.5px]">
        {delays.map((d, i) => (
          <span
            key={i}
            className={`size-[4px] bg-ink ${round ? "rounded-full" : "rounded-[1px]"}`}
            style={{
              opacity: d === null ? 0.07 : 0.15,
              animation:
                d === null ? "none" : `pixel-on ${dur}ms ease-in-out ${d}ms infinite`,
            }}
          />
        ))}
      </span>
      <span
        className="bg-clip-text text-[13px] font-medium text-transparent"
        style={{
          backgroundImage:
            "linear-gradient(90deg, var(--ink-3) 35%, var(--ink) 50%, var(--ink-3) 65%)",
          backgroundSize: "200% 100%",
          animation: "shimmer-text 1.4s linear infinite",
        }}
      >
        {displayLabel}
      </span>
      <span className="font-mono text-[12px] text-ink-3 tabular-nums">
        {elapsed}
      </span>
    </div>
  );
}

"use client";

import React, { createContext, useContext, useEffect, useState } from "react";

export type Lang = "en" | "zh";

interface LangContextType {
  globalLang: Lang;
  setGlobalLang: (lang: Lang) => void;
  componentLangs: Record<string, Lang>;
  setComponentLang: (id: string, lang: Lang) => void;
  getLang: (id?: string, override?: Lang) => Lang;
}

const LangContext = createContext<LangContextType>({
  globalLang: "en",
  setGlobalLang: () => {},
  componentLangs: {},
  setComponentLang: () => {},
  getLang: () => "en",
});

export function LangProvider({ children }: { children: React.ReactNode }) {
  const [globalLang, setGlobalLangState] = useState<Lang>("en");
  const [componentLangs, setComponentLangs] = useState<Record<string, Lang>>({});

  // Restore the persisted global language on mount.
  useEffect(() => {
    try {
      const stored = window.localStorage.getItem("nai-lang");
      if (stored === "en" || stored === "zh") setGlobalLangState(stored);
    } catch {}
  }, []);

  useEffect(() => {
    document.documentElement.lang = globalLang;
  }, [globalLang]);

  const setGlobalLang = (lang: Lang) => {
    setGlobalLangState(lang);
    try {
      window.localStorage.setItem("nai-lang", lang);
    } catch {}
  };

  const setComponentLang = (id: string, lang: Lang) => {
    setComponentLangs((prev) => ({ ...prev, [id]: lang }));
  };

  const getLang = (id?: string, override?: Lang): Lang => {
    if (override) return override;
    if (id && componentLangs[id]) return componentLangs[id];
    return globalLang;
  };

  return (
    <LangContext.Provider
      value={{
        globalLang,
        setGlobalLang,
        componentLangs,
        setComponentLang,
        getLang,
      }}
    >
      {children}
    </LangContext.Provider>
  );
}

export function useLang(id?: string, override?: Lang): Lang {
  const ctx = useContext(LangContext);
  return override ?? ctx.getLang(id);
}

export function useLangContext() {
  return useContext(LangContext);
}
